<?php
require_once 'config.php';$admin_id=require_admin($conn);
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['change_role'])){
 check_csrf();$id=(int)($_POST['user_id']??0);$role=$_POST['user_type']??'';
 if(!in_array($role,['user','admin'],true)||$id<1){flash('error','Некоректна роль або користувач.');redirect_to('admin_users.php');}
 if($id===$admin_id){flash('error','Не можна змінити роль власного облікового запису тут.');redirect_to('admin_users.php');}
 $q=$conn->prepare('UPDATE users SET user_type=? WHERE id=?');$q->bind_param('si',$role,$id);$q->execute();flash('success','Роль користувача змінено.');redirect_to('admin_users.php');
}
$search=trim($_GET['q']??'');$search=mb_substr($search,0,80);
if($search==='')$users=$conn->query('SELECT id,name,email,user_type FROM users ORDER BY id DESC LIMIT 200')->fetch_all(MYSQLI_ASSOC);
else{$s='%'.$search.'%';$q=$conn->prepare('SELECT id,name,email,user_type FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 200');$q->bind_param('ss',$s,$s);$q->execute();$users=$q->get_result()->fetch_all(MYSQLI_ASSOC);}
?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Користувачі · flora.atelier admin</title><link rel="stylesheet" href="css/admin_style.css"><link rel="stylesheet" href="css/flor-admin-v8.css"></head><body><?php require 'admin_header.php';?><div class="admin-page-head"><div><span class="admin-eyebrow">НАША СПІЛЬНОТА</span><h1>Користувачі <em>♙</em></h1><p>Керуйте ролями та знаходьте облікові записи.</p></div></div><section class="admin-card"><div class="card-heading"><h2>Список користувачів</h2><form class="admin-search"><input name="q" value="<?=e($search)?>" placeholder="Ім’я або email"><button>Знайти</button></form></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>Ім’я</th><th>Email</th><th>Роль</th><th>Налаштування</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td>#<?=(int)$u['id']?></td><td><b><?=e($u['name'])?></b><?=$admin_id===(int)$u['id']?' · (ви)':''?></td><td><?=e($u['email'])?></td><td><span class="status-pill <?=$u['user_type']==='admin'?'approved':'pending'?>"><?=$u['user_type']==='admin'?'Адміністратор':'Покупець'?></span></td><td><?php if($admin_id===(int)$u['id']):?><small>Власна роль захищена</small><?php else:?><form method="post" class="inline-form"><?=csrf_input()?><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><select name="user_type"><option value="user" <?=$u['user_type']==='user'?'selected':''?>>Покупець</option><option value="admin" <?=$u['user_type']==='admin'?'selected':''?>>Адміністратор</option></select><button class="admin-btn compact" name="change_role" value="1" data-confirm="Змінити роль цього користувача?">Зберегти</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="5">Нічого не знайдено.</td></tr><?php endif;?></tbody></table></div></section><p class="admin-note">Облікові записи не видаляються з панелі, щоб випадково не втратити історію замовлень і відгуки.</p><?php require 'admin_footer.php';?></body></html>
